/// Returns `true` if `n` is even.
fn is_even_exec(n: u32) -> bool {
    n % 2 == 0
}

/// Returns `true` if and only if there exists at least one even number in `arr`.
/// If `arr` is empty, returns `false`.
fn is_product_even(arr: &Vec<u32>) -> bool {
    arr.iter().any(|&n| is_even_exec(n))
}

